import { chromium } from 'playwright';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';

// Build a short onboarding story from a fresh, real demo run. Instructional
// labels are presentation; findings, scores, evidence, and progress come from
// stored Gremlin artifacts generated by scripts/demo.mjs.
const report = JSON.parse(
  await readFile('artifacts/broken/report.json', 'utf8'),
);
const comparison = JSON.parse(
  await readFile('artifacts/comparison.json', 'utf8'),
);
const transcript = await readFile('artifacts/broken/terminal.txt', 'utf8');
const progress = transcript
  .split('\n')
  .map((line) => line.trim())
  .filter((line) => line.startsWith('Testing '));

const finding =
  report.findings.find((item) =>
    item.title.includes('Empty required values'),
  ) || report.findings.find((item) => item.screenshot);

if (!finding?.screenshot) {
  throw new Error('Capture needs a real finding with screenshot evidence.');
}
if (progress.length < 5) {
  throw new Error('Capture needs progress from all five Gremlin families.');
}

const escapeHtml = (value) =>
  String(value).replace(
    /[&<>"']/g,
    (char) =>
      ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;',
      })[char],
  );

const score = report.score.value;
const high = report.findings.filter((item) => item.severity === 'high').length;
const medium = report.findings.filter(
  (item) => item.severity === 'medium',
).length;
const low = report.findings.filter((item) => item.severity === 'low').length;
const evidenceUrl = pathToFileURL(
  resolve('artifacts/broken', finding.screenshot),
).href;

const baseCss = `
  *{box-sizing:border-box}
  html,body{margin:0;width:100%;height:100%;background:#0b0e0b;color:#f3f5eb}
  body{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;overflow:hidden}
  .screen{width:1200px;height:675px;padding:34px 42px 32px;position:relative;background:radial-gradient(circle at 85% -10%,rgba(190,255,72,.09),transparent 28%),#0b0e0b}
  .top{height:46px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #283026;padding-bottom:15px}
  .brand{font-weight:900;font-size:24px;letter-spacing:-.04em}.brand b{color:#baff45}.eyebrow{font:700 12px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.14em;color:#91a08a;text-transform:uppercase}
  .steps{display:flex;gap:8px}.step{font:700 11px ui-monospace,SFMono-Regular,Menlo,monospace;padding:7px 10px;border:1px solid #30382d;color:#71806b}.step.on{border-color:#baff45;color:#baff45;background:#172013}
  h1{font-size:50px;line-height:1.02;letter-spacing:-.045em;margin:0;max-width:900px}h2{font-size:31px;line-height:1.08;letter-spacing:-.03em;margin:0}
  .muted{color:#aeb8a8}.green{color:#baff45}.red{color:#ff726b}.yellow{color:#ffd76a}
  .terminal{background:#111510;border:1px solid #313a2e;border-radius:10px;padding:25px 28px;font:19px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;box-shadow:0 22px 70px rgba(0,0,0,.28)}
  .prompt{color:#baff45}.dim{color:#7f8c79}.line{display:flex;justify-content:space-between;gap:18px;padding:7px 0;border-bottom:1px solid #1e251c}.line:last-child{border:0}.status{white-space:nowrap;color:#ff8c7f}
  .pill{display:inline-flex;border:1px solid #364032;border-radius:999px;padding:7px 11px;font:700 11px ui-monospace,SFMono-Regular,Menlo,monospace;color:#bac5b3;margin-right:7px}.pill.hot{border-color:#baff45;color:#baff45}
  .card{border:1px solid #30392d;background:#111510;border-radius:10px;padding:24px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:22px}.label{font:700 11px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.12em;text-transform:uppercase;color:#8d9a86;margin-bottom:10px}
  .bigscore{font-size:92px;font-weight:900;line-height:.9;letter-spacing:-.07em;color:#baff45}.slash{font-size:30px;color:#91a08a;letter-spacing:-.03em}.metric{font:700 15px ui-monospace,SFMono-Regular,Menlo,monospace;color:#d8ded2}
  .footer{position:absolute;left:42px;right:42px;bottom:26px;display:flex;justify-content:space-between;align-items:center;color:#7f8b79;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}
  .browser{background:#f7f8f2;border:1px solid #3b4438;border-radius:10px;overflow:hidden}.chrome{height:34px;background:#171c16;border-bottom:1px solid #30382e;display:flex;align-items:center;gap:7px;padding:0 12px}.dot{width:8px;height:8px;border-radius:50%;background:#596353}.urlbar{height:18px;border-radius:5px;background:#252d23;margin-left:8px;flex:1}.browser img{display:block;width:100%;height:100%;object-fit:cover;object-position:top left}
  .findingTitle{font-size:34px;line-height:1.08;letter-spacing:-.035em;margin:8px 0 12px}.quote{border-left:3px solid #baff45;padding-left:14px;color:#dfe6d7;font-size:17px;line-height:1.45}.path{font:13px ui-monospace,SFMono-Regular,Menlo,monospace;color:#baff45}
`;

const steps = (active) =>
  ['RUN', 'WATCH', 'FIND', 'REPORT']
    .map(
      (label, index) =>
        `<span class="step ${index === active ? 'on' : ''}">${index + 1} ${label}</span>`,
    )
    .join('');

const frame = (active, body, footerLeft, footerRight = 'REAL LOCAL RUN') => `
<!doctype html><meta charset="utf-8"><style>${baseCss}</style>
<div class="screen">
  <div class="top"><div class="brand">👹 GREMLIN<b>_</b></div><div class="steps">${steps(active)}</div></div>
  ${body}
  <div class="footer"><span>${escapeHtml(footerLeft)}</span><span>${escapeHtml(footerRight)}</span></div>
</div>`;

const commandFrame = frame(
  0,
  `<div style="padding-top:66px">
    <div class="eyebrow">UX chaos testing in one command</div>
    <h1 style="margin-top:14px">Find the UX bugs<br>you didn't know to test for.</h1>
    <div class="terminal" style="margin-top:42px"><span class="dim">$</span> <span class="prompt">npm run gremlin -- http://localhost:3000</span></div>
    <div style="margin-top:22px"><span class="pill hot">NO CONFIG</span><span class="pill">LOCAL ONLY</span><span class="pill">REAL BROWSER</span><span class="pill">GUARDED NETWORK</span></div>
  </div>`,
  'Start your app. Point Gremlin at localhost. Press Enter.',
);

const progressFrame = (count) =>
  frame(
    1,
    `<div style="padding-top:45px">
      <div class="eyebrow">Gremlin entered your app</div>
      <h2 style="margin-top:10px">Now use it like an impatient human.</h2>
      <div class="terminal" style="margin-top:28px;padding-top:18px;padding-bottom:18px">
        ${progress
          .map((line, index) => {
            const visible = index < count;
            const label = line.replace(/….*$/, '…');
            return `<div class="line" style="opacity:${visible ? 1 : 0.32}"><span>${escapeHtml(label)}</span><span class="status">${visible ? '💥 findings' : 'waiting'}</span></div>`;
          })
          .join('')}
      </div>
      <div style="margin-top:18px;color:#97a491;font-size:15px">Mobile layouts · invalid forms · history · keyboard flow · rapid interaction</div>
    </div>`,
    `${report.scenarios.length} scenarios in this real demo run`,
  );

const findingFrame = frame(
  2,
  `<div class="grid2" style="padding-top:38px;grid-template-columns:.9fr 1.1fr;align-items:stretch">
    <div class="card" style="height:510px;display:flex;flex-direction:column;justify-content:center">
      <div class="label"><span class="red">HIGH</span> · ${escapeHtml(finding.gremlin || finding.category)} · ${escapeHtml(finding.id)}</div>
      <div class="findingTitle">${escapeHtml(finding.title)}</div>
      <div class="muted" style="font-size:17px;line-height:1.5">${escapeHtml(finding.description)}</div>
      <div class="quote" style="margin-top:26px">${escapeHtml(finding.personalityLine || 'I found something your happy path missed.')}</div>
      <div class="path" style="margin-top:24px">screenshot evidence saved automatically →</div>
    </div>
    <div class="browser" style="height:510px"><div class="chrome"><span class="dot"></span><span class="dot"></span><span class="dot"></span><span class="urlbar"></span></div><div style="height:476px"><img src="${evidenceUrl}"></div></div>
  </div>`,
  'Observed browser behavior, selector, reproduction steps, and screenshot stay together.',
);

const reportImageUrl = pathToFileURL(resolve('assets/report.png')).href;
const reportFrame = frame(
  3,
  `<div style="padding-top:32px">
    <div style="display:flex;align-items:end;justify-content:space-between;margin-bottom:20px">
      <div><div class="eyebrow">Generated automatically</div><h2 style="margin-top:8px">One report your team can actually use.</h2></div>
      <div class="metric"><span class="red">${high} high</span> · <span class="yellow">${medium} medium</span> · ${low} low</div>
    </div>
    <div class="browser" style="height:455px"><div class="chrome"><span class="dot"></span><span class="dot"></span><span class="dot"></span><span class="urlbar"></span></div><div style="height:421px;overflow:hidden"><img src="${reportImageUrl}" style="object-fit:cover;object-position:top"></div></div>
  </div>`,
  'report.html · report.json · screenshots/',
);

const compareFrame = frame(
  3,
  `<div style="padding-top:62px;text-align:center">
    <div class="eyebrow">Fix → rerun → compare</div>
    <h1 style="margin:14px auto 0;max-width:850px">Make the bugs disappear.<br>Then prove it.</h1>
    <div style="display:flex;justify-content:center;align-items:center;gap:42px;margin-top:48px">
      <div class="card" style="width:300px;text-align:left"><div class="label">BEFORE</div><div class="bigscore" style="color:#ff726b">${comparison.before.score.value}<span class="slash">/100</span></div><div class="muted" style="margin-top:14px">${comparison.commonCoverage.beforePassed}/${comparison.commonCoverage.evaluated} matched attacks survived</div></div>
      <div style="font-size:38px;color:#667260">→</div>
      <div class="card" style="width:300px;text-align:left"><div class="label">AFTER</div><div class="bigscore">${comparison.after.score.value}<span class="slash">/100</span></div><div class="muted" style="margin-top:14px">${comparison.commonCoverage.afterPassed}/${comparison.commonCoverage.evaluated} matched attacks survived</div></div>
    </div>
  </div>`,
  `Backend writes in demo: ${comparison.backendWrites} · dangerous actions: ${comparison.dangerousActions}`,
);

const finalFrame = frame(
  0,
  `<div style="padding-top:76px;text-align:center">
    <div class="eyebrow">That's the workflow</div>
    <h1 style="margin:15px auto 0;max-width:900px">Your tests check what you expected.<br><span class="green">Gremlin explores what you didn't.</span></h1>
    <div class="terminal" style="margin:44px auto 0;max-width:850px;text-align:left"><span class="dim">$</span> <span class="prompt">npm run gremlin -- http://localhost:3000</span></div>
    <div style="margin-top:20px;color:#aab5a4">Run → watch → inspect evidence → fix → rerun.</div>
  </div>`,
  'github.com/HyperOrb/gremlin-ui',
  'NO AI KEY · NO ACCOUNT · MIT',
);

await mkdir('assets', { recursive: true });
await mkdir('artifacts/capture', { recursive: true });

const browser = await chromium.launch();
try {
  const page = await browser.newPage({
    viewport: { width: 1200, height: 675 },
    deviceScaleFactor: 1,
  });

  // Keep the standalone README report image fresh too.
  await page.goto(pathToFileURL(resolve('artifacts/broken/report.html')).href);
  await page.screenshot({ path: 'assets/report.png' });

  const scenes = [
    ['00-command', commandFrame, 2.4],
    ['01-watch-mobile', progressFrame(1), 0.8],
    ['02-watch-forms', progressFrame(3), 0.8],
    ['03-watch-all', progressFrame(5), 1.8],
    ['04-finding', findingFrame, 3.0],
    ['05-report', reportFrame, 2.8],
    ['06-compare', compareFrame, 2.5],
    ['07-final', finalFrame, 2.2],
  ];

  for (const [name, html] of scenes) {
    await page.setContent(html, { waitUntil: 'load' });
    await page.screenshot({ path: `artifacts/capture/${name}.png` });
  }

  const manifest =
    scenes
      .map(
        ([name, , duration]) =>
          `file '${resolve(`artifacts/capture/${name}.png`)}'\nduration ${duration}`,
      )
      .join('\n') + `\nfile '${resolve('artifacts/capture/07-final.png')}'\n`;
  await writeFile('artifacts/capture/frames.txt', manifest);
} finally {
  await browser.close();
}

const ffmpeg = spawnSync(
  'ffmpeg',
  [
    '-y',
    '-f',
    'concat',
    '-safe',
    '0',
    '-i',
    'artifacts/capture/frames.txt',
    '-vf',
    'fps=10,scale=960:-2:flags=lanczos,split[s0][s1];[s0]palettegen=max_colors=128[p];[s1][p]paletteuse=dither=bayer:bayer_scale=3',
    '-loop',
    '0',
    'assets/demo.gif',
  ],
  { encoding: 'utf8' },
);

if (ffmpeg.error?.code === 'ENOENT') {
  console.error(
    'Frames captured. Install ffmpeg, then rerun: node scripts/capture.mjs',
  );
  process.exitCode = 2;
} else if (ffmpeg.status !== 0) {
  console.error(ffmpeg.stderr);
  process.exitCode = 2;
} else {
  console.log(
    `Created assets/demo.gif: real ${score}/100 demo findings → evidence → report → ${comparison.after.score.value}/100 rerun.`,
  );
}
